inline auto BarFontLookup(uint32_t codepoint) -> uint16_t
{
    if (codepoint >= 32 && codepoint <= 126)
        return static_cast<uint16_t>(codepoint - 31);
    uint32_t lo = 0, hi = kBarFontGlyphCount;
    while (lo < hi)
    {
        uint32_t mid = lo + (hi - lo) / 2;
        if (kBarFontMap[mid].codepoint < codepoint) lo = mid + 1;
        else hi = mid;
    }
    if (lo < kBarFontGlyphCount && kBarFontMap[lo].codepoint == codepoint)
        return kBarFontMap[lo].glyphIndex;
    return static_cast<uint16_t>(kBarFontGlyphCount);
}

inline auto Utf8Decode(const uint8_t *&p, uint64_t &remaining) -> uint32_t
{
    if (remaining == 0) return 0;
    uint8_t c = *p;
    if (c < 0x80) { ++p; --remaining; return c; }
    uint32_t cp; uint32_t n;
    if ((c & 0xE0) == 0xC0)      { cp = c & 0x1F; n = 1; }
    else if ((c & 0xF0) == 0xE0) { cp = c & 0x0F; n = 2; }
    else if ((c & 0xF8) == 0xF0) { cp = c & 0x07; n = 3; }
    else { ++p; --remaining; return 0; }
    ++p; --remaining;
    for (uint32_t i = 0; i < n; ++i)
    {
        if (remaining == 0 || (p[0] & 0xC0) != 0x80) return 0;
        cp = (cp << 6) | (p[0] & 0x3F);
        ++p; --remaining;
    }
    return cp;
}
